import{_ as t,o as s,c as n,b6 as i}from"./chunks/framework.BUXTSoD9.js";const m=JSON.parse('{"title":"Concevoir des pages et des boutons en référençant les guidelines UI","description":"","frontmatter":{},"headers":[],"relativePath":"fr-fr/stage-2/frontend/multi-product-ui/index.md","filePath":"fr-fr/stage-2/frontend/multi-product-ui/index.md"}'),a={name:"fr-fr/stage-2/frontend/multi-product-ui/index.md"};function l(r,e,o,u,d,p){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="concevoir-des-pages-et-des-boutons-en-referencant-les-guidelines-ui" tabindex="-1">Concevoir des pages et des boutons en référençant les guidelines UI <a class="header-anchor" href="#concevoir-des-pages-et-des-boutons-en-referencant-les-guidelines-ui" aria-label="Permalink to “Concevoir des pages et des boutons en référençant les guidelines UI”">​</a></h1><p>Beaucoup de gens disent « Je voudrais que ma page ressemble davantage à Apple » ou « J&#39;aimerais des boutons plus sophistiqués », mais quand il s&#39;agit de passer à l&#39;action, ils se heurtent souvent à une question :</p><p><strong>Que faut-il référencer exactement ?</strong></p><p>Copier des captures d&#39;écran ne vous apprend qu&#39;à « ressembler ou non ». Mais en ouvrant les guidelines de design d&#39;Apple, Google, Microsoft et Atlassian, vous découvrirez que leur véritable force n&#39;est pas le style visuel, mais la <strong>manière dont ils expliquent clairement les problèmes de design</strong> : ce qu&#39;une page doit mettre en avant, comment hiérarchiser les boutons, comment mettre en évidence les actions — ces critères de jugement sont le cœur du sujet.</p><blockquote><p>Référencer les guidelines de design n&#39;a pas pour but de « ressembler à quelqu&#39;un », mais d&#39;apprendre comment les autres prennent des décisions.</p></blockquote><div class="info custom-block"><p class="custom-block-title">Pourquoi apprendre cela aujourd&#39;hui encore</p><p>Les règles de design ont déjà été intégrées dans les modèles par l&#39;entraînement, absorbées par défaut dans les outils de conception, et même assimilées par l&#39;IA à partir de quelques captures d&#39;écran. Mais il reste nécessaire de savoir d&#39;où viennent ces règles et pourquoi elles sont ainsi définies.</p></div><h2 id="quelques-citations-originales-pour-mesurer-l-ecart" tabindex="-1">Quelques citations originales pour mesurer l&#39;écart <a class="header-anchor" href="#quelques-citations-originales-pour-mesurer-l-ecart" aria-label="Permalink to “Quelques citations originales pour mesurer l&#39;écart”">​</a></h2><p>Si vous pensiez que « les guidelines de design, c&#39;est juste parler de style », lisez d&#39;abord quelques citations officielles.</p><p>Dans une équipe, on entend souvent dire des choses comme :</p><ul><li>Fais un menu déroulant</li><li>Mets un menu ici</li><li>Ajoute quelques fonctionnalités dans la barre de menus</li><li>Mets deux boutons ici, un pour confirmer et un pour annuler</li></ul><p>Cela semble correct, mais dans les guidelines des grandes entreprises, ces termes ne sont pas des concepts flous — ils sont décomposés de manière très précise.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ce qu&#39;on dit couramment</th><th style="text-align:left;">Citation officielle</th><th style="text-align:left;">En résumé</th></tr></thead><tbody><tr><td style="text-align:left;">« Fais un menu »</td><td style="text-align:left;">Apple : <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">« A menu reveals its options... »</a></td><td style="text-align:left;"><code>Menu</code> sert à effectuer des actions</td></tr><tr><td style="text-align:left;">« Mets des fonctionnalités dans la barre de menus »</td><td style="text-align:left;">Apple : <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">« menu bar menus contain all the commands... »</a></td><td style="text-align:left;">C&#39;est le menu de commandes de l&#39;application en haut</td></tr><tr><td style="text-align:left;">« Fais un menu déroulant »</td><td style="text-align:left;">Apple : <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">« A pop-up list lets the user choose one option among several. »</a></td><td style="text-align:left;"><code>pop-up</code> sert à choisir une option dans une liste</td></tr><tr><td style="text-align:left;">« Fais aussi un menu déroulant »</td><td style="text-align:left;">Apple : <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">« A pull-down list is generally used for selecting commands in a specific context. »</a></td><td style="text-align:left;"><code>pull-down</code> sert à déclencher des commandes dans le contexte actuel</td></tr><tr><td style="text-align:left;">« Un menu peut aussi servir à filtrer »</td><td style="text-align:left;">Fluent : <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">« If you need to collect information from people, try a select, dropdown, or combobox instead. »</a></td><td style="text-align:left;"><code>Menu</code> ne sert pas à sélectionner des valeurs</td></tr><tr><td style="text-align:left;">« Un menu peut servir de navigation »</td><td style="text-align:left;">Material : <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">« Menus should not be used as a primary method for navigation within an app. »</a></td><td style="text-align:left;"><code>Menu</code> n&#39;est pas une navigation principale</td></tr><tr><td style="text-align:left;">« Mets juste OK / Annuler sur les boutons »</td><td style="text-align:left;">Apple : <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">« Always use &#39;Cancel&#39; to title a button that cancels the alert&#39;s action. »</a></td><td style="text-align:left;">Le texte des boutons ne s&#39;écrit pas au hasard</td></tr></tbody></table><blockquote><p>Les citations du tableau sont toutes cliquables et renvoient vers les pages officielles correspondantes.</p></blockquote><p>C&#39;est la chose qui frappe le plus quand on lit vraiment des guidelines de design pour la première fois :</p><blockquote><p>Quand nous pensons discuter d&#39;UI, la plupart du temps nous ne faisons que communiquer avec un tas de termes vagues.</p></blockquote><p>Apple ne dit pas simplement « fais un menu » ; elle continue à distinguer :</p><ul><li><code>menu</code></li><li><code>menu bar menu</code></li><li><code>pop-up button</code></li><li><code>pull-down button</code></li><li><code>context menu</code></li></ul><p>Fluent ne dit pas simplement « menu déroulant » ; elle continue à distinguer :</p><ul><li><code>menu</code></li><li><code>dropdown</code></li><li><code>select</code></li><li><code>combobox</code></li></ul><p>C&#39;est ça, la nécessité des guidelines de design.</p><p>Ce n&#39;est pas pour rendre les pages plus professionnelles, mais pour que l&#39;équipe, lorsqu&#39;elle discute d&#39;UI, n&#39;ait plus chacun une idée différente en tête.</p><h2 id="ce-que-vous-allez-apprendre" tabindex="-1">Ce que vous allez apprendre <a class="header-anchor" href="#ce-que-vous-allez-apprendre" aria-label="Permalink to “Ce que vous allez apprendre”">​</a></h2><ol><li>Pourquoi il faut consulter les guidelines de design avant de concevoir des pages et des boutons</li><li>Quels contenus des guidelines d&#39;Apple, Material, Fluent et Atlassian méritent le plus d&#39;attention</li><li>Comment concevoir clairement la « hiérarchie des pages » et la « hiérarchie des boutons »</li><li>Comment faire en sorte que l&#39;IA référence les guidelines des autres pour générer des pages et des boutons</li></ol><h2 id="_1-pourquoi-les-guidelines-de-design-vous-aident-a-clarifier-les-pages" tabindex="-1">1. Pourquoi les guidelines de design vous aident à clarifier les pages <a class="header-anchor" href="#_1-pourquoi-les-guidelines-de-design-vous-aident-a-clarifier-les-pages" aria-label="Permalink to “1. Pourquoi les guidelines de design vous aident à clarifier les pages”">​</a></h2><p>Après avoir lu les citations ci-dessus, vous remarquerez un point essentiel :</p><p><strong>Les guidelines de design ne sont pas la cerise sur le gâteau, elles servent d&#39;abord à employer les bons termes.</strong></p><p>Beaucoup de pages ne sont pas belles non pas parce que les couleurs ne sont pas assez sophistiquées, mais parce que la hiérarchie de l&#39;information est chaotique.</p><p>Beaucoup de boutons ne sont pas pratiques non pas parce que les coins arrondis sont mal choisis, mais parce que :</p><ul><li>Il y a trop de boutons principaux, l&#39;utilisateur ne sait pas lequel cliquer</li><li>Les boutons dangereux et les boutons normaux se ressemblent</li><li>Tous les boutons de la page se disputent l&#39;attention</li><li>Les styles et la sémantique des boutons sont incohérents d&#39;une page à l&#39;autre</li></ul><p>Les guidelines de design matures résolvent précisément ces problèmes. Elles définissent généralement :</p><table tabindex="0"><thead><tr><th style="text-align:left;">Contenu de la guideline</th><th style="text-align:left;">Quel problème elle résout</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Hiérarchie des pages</strong></td><td style="text-align:left;">Que regarder en premier, ensuite, comment organiser l&#39;information</td></tr><tr><td style="text-align:left;"><strong>Fondements visuels</strong></td><td style="text-align:left;">Couleurs, espacements, typographie, coins arrondis, ombres — comment uniformiser</td></tr><tr><td style="text-align:left;"><strong>Hiérarchie des boutons</strong></td><td style="text-align:left;">Comment distinguer les boutons principaux, secondaires, textuels et dangereux</td></tr><tr><td style="text-align:left;"><strong>Règles d&#39;états</strong></td><td style="text-align:left;">Comment afficher hover, focus, disabled, loading</td></tr><tr><td style="text-align:left;"><strong>Sémantique d&#39;interaction</strong></td><td style="text-align:left;">Quel bouton est « confirmer », lequel est « annuler », lequel est « plus d&#39;actions »</td></tr></tbody></table><p>Ainsi, ce que les guidelines de design fournissent véritablement, ce n&#39;est pas un « habillage », mais un ensemble de <strong>critères de jugement</strong>.</p><h2 id="_2-que-regarder-en-priorite-dans-les-guidelines-des-grandes-entreprises" tabindex="-1">2. Que regarder en priorité dans les guidelines des grandes entreprises <a class="header-anchor" href="#_2-que-regarder-en-priorite-dans-les-guidelines-des-grandes-entreprises" aria-label="Permalink to “2. Que regarder en priorité dans les guidelines des grandes entreprises”">​</a></h2><h3 id="_2-1-referencer-apple-apprendre-a-«-definir-les-choses-assez-finement-»" tabindex="-1">2.1 Référencer Apple : apprendre à « définir les choses assez finement » <a class="header-anchor" href="#_2-1-referencer-apple-apprendre-a-«-definir-les-choses-assez-finement-»" aria-label="Permalink to “2.1 Référencer Apple : apprendre à « définir les choses assez finement »”">​</a></h3><p>Ce qu&#39;il y a de plus précieux chez Apple, ce n&#39;est pas seulement la retenue visuelle, mais le fait qu&#39;elle définit les concepts de manière très précise.</p><p>Pour ce que beaucoup d&#39;équilles appellent « menu » ou « menu déroulant », Apple va encore plus loin :</p><ul><li><code>menu</code> : un ensemble de commandes, d&#39;options ou d&#39;états</li><li><code>menu bar menu</code> : collection de commandes au niveau de l&#39;application</li><li><code>pop-up button</code> : choisir une valeur</li><li><code>pull-down button</code> : déclencher une commande dans le contexte actuel</li><li><code>context menu</code> : actions courantes liées à l&#39;objet ou à la tâche en cours</li></ul><p>Cette distinction est très importante, car elle affecte directement :</p><ul><li>Ce composant sert-il à choisir une valeur ou à effectuer une action</li><li>Appartient-il à une partie de la page ou au niveau de l&#39;application</li><li>Doit-il afficher en permanence la valeur sélectionnée ou s&#39;ouvrir temporairement pour des commandes</li></ul><p>Quand vous commencez à penser à ce niveau de granularité, vos pages deviennent immédiatement beaucoup plus claires.</p><h3 id="_2-2-referencer-apple-apprendre-la-hierarchie-des-pages-et-la-retenue" tabindex="-1">2.2 Référencer Apple : apprendre la hiérarchie des pages et la retenue <a class="header-anchor" href="#_2-2-referencer-apple-apprendre-la-hierarchie-des-pages-et-la-retenue" aria-label="Permalink to “2.2 Référencer Apple : apprendre la hiérarchie des pages et la retenue”">​</a></h3><p>Les Apple Human Interface Guidelines sont particulièrement adaptées pour apprendre deux choses :</p><ul><li>Comment établir une hiérarchie claire dans une page</li><li>Comment les contrôles restent explicites sans voler la vedette</li></ul><p>Apple met l&#39;accent sur <code>Hierarchy</code>, <code>Harmony</code>, <code>Consistency</code>. Cela signifie que la conception de la page doit répondre à :</p><ul><li>Quelle est l&#39;information la plus importante de la page actuelle</li><li>Quelle est la tâche principale de l&#39;utilisateur</li><li>Quelle action doit être la plus visible, et quelle action doit s&#39;effacer</li></ul><p>Si vous référencez Apple pour concevoir des pages, vous pouvez vous inspirer de :</p><ul><li>Ne pas trop fragmenter l&#39;information au-dessus de la ligne de flottaison, concentrez-vous d&#39;abord sur le contenu essentiel</li><li>Utiliser l&#39;espace blanc, la taille de police et le regroupement pour établir l&#39;ordre, plutôt qu&#39;empiler des bordures</li><li>Ne pas mettre tous les boutons en forte emphase, seules les actions clés doivent être les plus visibles</li></ul><h3 id="_2-3-referencer-material-apprendre-une-structure-de-page-claire" tabindex="-1">2.3 Référencer Material : apprendre une structure de page claire <a class="header-anchor" href="#_2-3-referencer-material-apprendre-une-structure-de-page-claire" aria-label="Permalink to “2.3 Référencer Material : apprendre une structure de page claire”">​</a></h3><p>Material Design est très adapté pour apprendre « comment une page organise les flux de tâches ».</p><p>Beaucoup de ses composants et spécifications de mise en page ont pour cœur de vous aider à clarifier :</p><ul><li>La page est-elle de type navigation ou exécution de tâche</li><li>La page actuelle demande-t-elle à l&#39;utilisateur de lire, de choisir ou de soumettre</li><li>Dans une page, quels éléments doivent être stables et répétés, et quels éléments doivent répondre aux changements de contexte</li></ul><p>Si vous référencez Material pour concevoir des pages, vous pouvez vous inspirer de :</p><ul><li>Des blocs de page clairs, avec des responsabilités de modules bien définies</li><li>Une répartition claire entre navigation, zone de contenu et zone d&#39;actions</li><li>Des styles de boutons différents correspondant à des priorités d&#39;action différentes</li></ul><h3 id="_2-4-referencer-fluent-apprendre-les-frontieres-des-composants-et-la-hierarchie-des-boutons" tabindex="-1">2.4 Référencer Fluent : apprendre les frontières des composants et la hiérarchie des boutons <a class="header-anchor" href="#_2-4-referencer-fluent-apprendre-les-frontieres-des-composants-et-la-hierarchie-des-boutons" aria-label="Permalink to “2.4 Référencer Fluent : apprendre les frontières des composants et la hiérarchie des boutons”">​</a></h3><p>Fluent 2 est très adapté aux back-offices, aux produits de type outils et aux systèmes de formulaires complexes. Son point le plus précieux est qu&#39;il vous dit directement « ne mélangez pas les concepts ».</p><p>Par exemple, il indique clairement : si vous devez « collect information », n&#39;utilisez plus <code>menu</code>, mais envisagez plutôt <code>select</code>, <code>dropdown</code>, <code>combobox</code>.</p><p>Cette phrase est très importante, car elle brise l&#39;idée que beaucoup de gens se font que « c&#39;est à peu près pareil ».</p><p>Fluent 2 attache aussi beaucoup d&#39;importance à :</p><ul><li>La hiérarchie des actions</li><li>Les frontières sémantiques des composants</li><li>La clarté dans les scénarios d&#39;information dense</li></ul><p>Si vous référencez Fluent pour concevoir des boutons, vous pouvez vous inspirer de :</p><ul><li><code>Primary button</code> pour l&#39;action la plus importante de la zone</li><li><code>Secondary button</code> pour les actions de support</li><li>Les boutons à faible emphase comme <code>Subtle</code>, <code>Transparent</code> pour les actions qui ne doivent pas perturber le flux principal</li><li>Plus il y a de boutons dans une page, plus il faut contrôler la priorité visuelle</li></ul><h3 id="_2-5-referencer-atlassian-apprendre-a-gerer-systematiquement-les-pages-et-les-boutons" tabindex="-1">2.5 Référencer Atlassian : apprendre à gérer systématiquement les pages et les boutons <a class="header-anchor" href="#_2-5-referencer-atlassian-apprendre-a-gerer-systematiquement-les-pages-et-les-boutons" aria-label="Permalink to “2.5 Référencer Atlassian : apprendre à gérer systématiquement les pages et les boutons”">​</a></h3><p>L&#39;Atlassian Design System est particulièrement adapté quand « une équipe travaille sur beaucoup de pages ». Il met l&#39;accent sur :</p><ul><li>Les foundations comme base partagée</li><li>Les tokens comme méthode d&#39;unification des décisions visuelles</li><li>Les components comme éléments d&#39;interaction réutilisables</li></ul><p>Si vous référencez Atlassian pour les pages et les boutons, le plus précieux est :</p><ul><li>Faire des règles uniformes pour la taille, la couleur, les coins arrondis et l&#39;espacement des boutons</li><li>Fixer le rythme de la mise en page</li><li>Faire en sorte que des pages différentes, au contenu différent, partagent le même langage structurel</li></ul><h2 id="_3-quand-vous-concevez-des-pages-quels-points-des-guidelines-devez-vous-consulter" tabindex="-1">3. Quand vous concevez des pages, quels points des guidelines devez-vous consulter <a class="header-anchor" href="#_3-quand-vous-concevez-des-pages-quels-points-des-guidelines-devez-vous-consulter" aria-label="Permalink to “3. Quand vous concevez des pages, quels points des guidelines devez-vous consulter”">​</a></h2><p>Quand vous consultez un système de design, ne demandez pas d&#39;abord « cette page est-elle jolie », mais posez d&#39;abord les questions suivantes.</p><h3 id="_3-1-au-premier-coup-d-œil-la-priorite-est-elle-claire" tabindex="-1">3.1 Au premier coup d&#39;œil, la priorité est-elle claire <a class="header-anchor" href="#_3-1-au-premier-coup-d-œil-la-priorite-est-elle-claire" aria-label="Permalink to “3.1 Au premier coup d&#39;œil, la priorité est-elle claire”">​</a></h3><p>Une page comporte généralement au moins trois niveaux :</p><ul><li><strong>Information principale</strong> : le contenu le plus important de la page actuelle</li><li><strong>Information secondaire</strong> : contenu aidant à comprendre ou à compléter</li><li><strong>Actions secondaires</strong> : actions qui ne doivent pas perturber la tâche principale</li></ul><p>Si les trois niveaux ne sont pas séparés, la page sera « tout est important », ce qui équivaut à « rien n&#39;est important ».</p><h3 id="_3-2-la-mise-en-page-sert-elle-la-tache-plutot-qu-elle-n-empile-des-modules" tabindex="-1">3.2 La mise en page sert-elle la tâche plutôt qu&#39;elle n&#39;empile des modules <a class="header-anchor" href="#_3-2-la-mise-en-page-sert-elle-la-tache-plutot-qu-elle-n-empile-des-modules" aria-label="Permalink to “3.2 La mise en page sert-elle la tâche plutôt qu&#39;elle n&#39;empile des modules”">​</a></h3><p>En consultant les guidelines, prêtez attention à :</p><ul><li>La zone de titre indique-t-elle clairement l&#39;objectif de la page</li><li>La zone de contenu principal est-elle organisée autour de la tâche</li><li>Les boutons d&#39;action sont-ils proches du contenu associé</li><li>L&#39;information secondaire est-elle atténuée</li></ul><h3 id="_3-3-les-actions-dans-la-page-ont-elles-une-priorite" tabindex="-1">3.3 Les actions dans la page ont-elles une priorité <a class="header-anchor" href="#_3-3-les-actions-dans-la-page-ont-elles-une-priorite" aria-label="Permalink to “3.3 Les actions dans la page ont-elles une priorité”">​</a></h3><p>Beaucoup de pages montrent 6 boutons d&#39;un coup, et chacun ressemble à un CTA — c&#39;est typique d&#39;une hiérarchie hors de contrôle.</p><p>Une approche plus raisonnable :</p><ul><li>Une zone ne comporte généralement qu&#39;une seule action principale</li><li>Les actions secondaires peuvent utiliser des styles à bordure, textuels ou plus discrets</li><li>Les actions à risque ne doivent pas ressembler à l&#39;action principale</li></ul><h2 id="_4-quand-vous-concevez-des-boutons-quels-points-des-guidelines-devez-vous-consulter" tabindex="-1">4. Quand vous concevez des boutons, quels points des guidelines devez-vous consulter <a class="header-anchor" href="#_4-quand-vous-concevez-des-boutons-quels-points-des-guidelines-devez-vous-consulter" aria-label="Permalink to “4. Quand vous concevez des boutons, quels points des guidelines devez-vous consulter”">​</a></h2><p>Les boutons sont la partie la plus susceptible d&#39;être « conçue à la va-vite », mais aussi celle qui révèle le mieux la maturité d&#39;un système.</p><h3 id="_4-1-d-abord-la-«-semantique-»-des-boutons-puis-le-style" tabindex="-1">4.1 D&#39;abord la « sémantique » des boutons, puis le style <a class="header-anchor" href="#_4-1-d-abord-la-«-semantique-»-des-boutons-puis-le-style" aria-label="Permalink to “4.1 D&#39;abord la « sémantique » des boutons, puis le style”">​</a></h3><p>Ne pensez pas d&#39;abord « bouton bleu ou bouton noir », demandez-vous d&#39;abord quel est le rôle de ce bouton.</p><p>Les rôles courants des boutons peuvent être classés ainsi :</p><table tabindex="0"><thead><tr><th style="text-align:left;">Type de bouton</th><th style="text-align:left;">Rôle</th><th style="text-align:left;">Stratégie de style courante</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary</strong></td><td style="text-align:left;">L&#39;action la plus critique de la zone</td><td style="text-align:left;">Plein, contraste élevé, le plus visible</td></tr><tr><td style="text-align:left;"><strong>Secondary</strong></td><td style="text-align:left;">Action de support</td><td style="text-align:left;">Bordure ou emphase d&#39;un niveau inférieur</td></tr><tr><td style="text-align:left;"><strong>Tertiary / Text</strong></td><td style="text-align:left;">Action faible</td><td style="text-align:left;">Texte ou faible présence visuelle</td></tr><tr><td style="text-align:left;"><strong>Destructive</strong></td><td style="text-align:left;">Suppression, désactivation, vidage et autres actions à risque</td><td style="text-align:left;">Couleur d&#39;avertissement ou style de risque explicite</td></tr><tr><td style="text-align:left;"><strong>Icon button</strong></td><td style="text-align:left;">Action outil locale</td><td style="text-align:left;">Simple, proche du contexte</td></tr></tbody></table><h3 id="_4-2-pas-trop-de-boutons-primary-dans-une-page" tabindex="-1">4.2 Pas trop de boutons Primary dans une page <a class="header-anchor" href="#_4-2-pas-trop-de-boutons-primary-dans-une-page" aria-label="Permalink to “4.2 Pas trop de boutons Primary dans une page”">​</a></h3><p>C&#39;est le piège le plus courant pour les débutants.</p><p>S&#39;il y a 4 boutons principaux sur la page, cela revient à n&#39;avoir aucun bouton principal. Le sens d&#39;un bouton principal est précisément de « dire à l&#39;utilisateur ce qu&#39;il doit faire maintenant ».</p><p>Vous pouvez vous inspirer de la pratique commune de nombreux systèmes de design :</p><ul><li>Une zone principale ne conserve généralement qu&#39;un seul bouton principal</li><li>Annuler, retourner, fermer ne doivent généralement pas être au même niveau que le bouton de confirmation</li><li>Les actions supplémentaires sont placées dans des boutons secondaires ou des menus</li></ul><h3 id="_4-3-les-boutons-doivent-pouvoir-exprimer-les-changements-d-etat" tabindex="-1">4.3 Les boutons doivent pouvoir exprimer les changements d&#39;état <a class="header-anchor" href="#_4-3-les-boutons-doivent-pouvoir-exprimer-les-changements-d-etat" aria-label="Permalink to “4.3 Les boutons doivent pouvoir exprimer les changements d&#39;état”">​</a></h3><p>Les guidelines définissent généralement les états des boutons de manière très précise :</p><ul><li>État par défaut</li><li>État de survol</li><li>État de focus</li><li>État désactivé</li><li>État de chargement</li><li>État de danger</li></ul><p>C&#39;est important, car un bouton n&#39;est pas une image statique, mais l&#39;un des contrôles les plus fréquemment activés par l&#39;utilisateur.</p><h3 id="_4-4-le-texte-des-boutons-fait-aussi-partie-du-design" tabindex="-1">4.4 Le texte des boutons fait aussi partie du design <a class="header-anchor" href="#_4-4-le-texte-des-boutons-fait-aussi-partie-du-design" aria-label="Permalink to “4.4 Le texte des boutons fait aussi partie du design”">​</a></h3><p>Le texte des boutons n&#39;est pas qu&#39;une « question de rédaction », il influence directement la compréhension de l&#39;utilisateur.</p><p>Par exemple :</p><ul><li><code>Enregistrer</code></li><li><code>Enregistrer les modifications</code></li><li><code>Publier maintenant</code></li><li><code>Supprimer le projet</code></li><li><code>Déplacer vers la corbeille</code></li></ul><p>Ces textes transmettent des attentes psychologiques très différentes. Les guidelines matures exigent généralement que les labels des boutons expriment clairement l&#39;action, et non utilisent des termes vagues.</p><h2 id="_5-une-checklist-tres-pratique-pour-la-conception-de-pages-et-de-boutons" tabindex="-1">5. Une checklist très pratique pour la conception de pages et de boutons <a class="header-anchor" href="#_5-une-checklist-tres-pratique-pour-la-conception-de-pages-et-de-boutons" aria-label="Permalink to “5. Une checklist très pratique pour la conception de pages et de boutons”">​</a></h2><p>Quand vous concevez une page vous-même, vous pouvez passer rapidement en revue cette checklist :</p><h3 id="checklist-page" tabindex="-1">Checklist page <a class="header-anchor" href="#checklist-page" aria-label="Permalink to “Checklist page”">​</a></h3><ul><li>Le titre de la page indique-t-il clairement la tâche en cours</li><li>L&#39;information la plus importante au-dessus de la ligne de flottaison est-elle visible d&#39;un coup d&#39;œil</li><li>La page est-elle organisée selon le flux de tâches, et non selon ce qui vous vient à l&#39;esprit</li><li>Une seule zone ne comporte-t-elle qu&#39;une seule action principale</li><li>Le contenu secondaire est-il atténué de manière appropriée</li></ul><h3 id="checklist-boutons" tabindex="-1">Checklist boutons <a class="header-anchor" href="#checklist-boutons" aria-label="Permalink to “Checklist boutons”">​</a></h3><ul><li>Ce bouton est-il une action principale ou secondaire</li><li>Pourquoi mérite-t-il d&#39;être plus visible que les autres</li><li>Y a-t-il trop de boutons principaux dans la page</li><li>Les actions dangereuses sont-elles clairement identifiées</li><li>Le texte du bouton est-il suffisamment précis</li></ul><h2 id="_6-comment-utiliser-l-ia-en-referencant-les-guidelines-des-autres-pour-concevoir-des-pages" tabindex="-1">6. Comment utiliser l&#39;IA en référençant les guidelines des autres pour concevoir des pages <a class="header-anchor" href="#_6-comment-utiliser-l-ia-en-referencant-les-guidelines-des-autres-pour-concevoir-des-pages" aria-label="Permalink to “6. Comment utiliser l&#39;IA en référençant les guidelines des autres pour concevoir des pages”">​</a></h2><p>Cette section est la plus pratique.</p><p>Beaucoup de gens, quand ils demandent à l&#39;IA de concevoir une page, se contentent de dire :</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Aidez-moi à faire une page de paramètres, un peu plus sophistiquée, style Apple</span></span></code></pre></div><p>Ce type de prompt est trop vague, et l&#39;IA ne peut généralement imiter que « fond blanc, coins arrondis, ombres ».</p><p>Pour les débutants, l&#39;approche la plus pratique n&#39;est pas de résumer vous-même un long texte, mais de coller directement à l&#39;IA les <strong>phrases clés du texte officiel des guidelines</strong>.</p><p>Cette approche a deux avantages :</p><ul><li>Vous n&#39;avez pas besoin de « traduire » vous-même la pensée de design</li><li>L&#39;IA comprend plus facilement la page et les boutons selon les définitions officielles</li></ul><h3 id="_6-1-exemple-1-faire-concevoir-par-l-ia-une-page-de-parametres-en-referencant-apple" tabindex="-1">6.1 Exemple 1 : Faire concevoir par l&#39;IA une page de paramètres en référençant Apple <a class="header-anchor" href="#_6-1-exemple-1-faire-concevoir-par-l-ia-une-page-de-parametres-en-referencant-apple" aria-label="Permalink to “6.1 Exemple 1 : Faire concevoir par l&#39;IA une page de paramètres en référençant Apple”">​</a></h3><p>Trouvez d&#39;abord une citation d&#39;Apple :</p><blockquote><p><a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">« Establish a clear visual hierarchy... »</a></p></blockquote><p>Vous pouvez coller directement ceci à l&#39;IA :</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Référencez cette phrase des Apple Human Interface Guidelines :</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Aidez-moi à concevoir une page de paramètres de sécurité du compte.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">La hiérarchie de la page doit être claire, les informations importantes en premier, les groupes bien ordonnés.</span></span></code></pre></div><p>Le point clé de cette rédaction : vous n&#39;avez pas besoin d&#39;expliquer trop de choses vous-même, collez simplement les propres mots d&#39;Apple.</p><h3 id="_6-2-exemple-2-faire-concevoir-par-l-ia-les-boutons-d-un-back-office-en-referencant-fluent" tabindex="-1">6.2 Exemple 2 : Faire concevoir par l&#39;IA les boutons d&#39;un back-office en référençant Fluent <a class="header-anchor" href="#_6-2-exemple-2-faire-concevoir-par-l-ia-les-boutons-d-un-back-office-en-referencant-fluent" aria-label="Permalink to “6.2 Exemple 2 : Faire concevoir par l&#39;IA les boutons d&#39;un back-office en référençant Fluent”">​</a></h3><p>Trouvez d&#39;abord une citation de Fluent :</p><blockquote><p><a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">« Only use one primary button in a layout... »</a></p></blockquote><p>Vous pouvez coller directement ceci à l&#39;IA :</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Référencez cette phrase de Fluent 2 :</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Aidez-moi à concevoir les boutons d&#39;un back-office de gestion d&#39;équipe.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Le bouton d&#39;ajout de membre doit être le plus visible, les boutons d&#39;export, de filtrage et d&#39;actions supplémentaires plus discrets, le bouton de suppression mis en évidence séparément.</span></span></code></pre></div><p>Cette phrase est particulièrement adaptée aux débutants, car elle dit directement à l&#39;IA : ne pas mettre trop de boutons principaux dans une zone.</p><h3 id="_6-3-exemple-3-faire-concevoir-par-l-ia-en-referencant-simultanement-les-guidelines-de-page-et-de-boutons" tabindex="-1">6.3 Exemple 3 : Faire concevoir par l&#39;IA en référençant simultanément les guidelines de page et de boutons <a class="header-anchor" href="#_6-3-exemple-3-faire-concevoir-par-l-ia-en-referencant-simultanement-les-guidelines-de-page-et-de-boutons" aria-label="Permalink to “6.3 Exemple 3 : Faire concevoir par l&#39;IA en référençant simultanément les guidelines de page et de boutons”">​</a></h3><p>Vous pouvez aussi coller deux citations à la fois, pour que l&#39;IA référence à la fois la page et les boutons :</p><blockquote><p>Apple : <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">« Establish a clear visual hierarchy... »</a></p><p>Fluent : <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">« Only use one primary button in a layout... »</a></p></blockquote><p>Puis écrivez directement :</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Référencez les deux phrases de guidelines de design suivantes :</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Apple : &quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fluent : &quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Aidez-moi à concevoir une page de détail de projet.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">La page contient la présentation du projet, les membres, l&#39;activité récente et l&#39;accès aux paramètres.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">La hiérarchie de la page doit être claire, ne conserver qu&#39;un seul bouton principal, les autres boutons plus discrets.</span></span></code></pre></div><p>Cette approche est particulièrement adaptée aux débutants, car il vous suffit de savoir copier le texte officiel et d&#39;ajouter deux phrases sur vos besoins.</p><h2 id="_7-comment-utiliser-l-ia-en-referencant-les-guidelines-de-boutons-pour-generer-directement-des-boutons" tabindex="-1">7. Comment utiliser l&#39;IA en référençant les guidelines de boutons pour générer directement des boutons <a class="header-anchor" href="#_7-comment-utiliser-l-ia-en-referencant-les-guidelines-de-boutons-pour-generer-directement-des-boutons" aria-label="Permalink to “7. Comment utiliser l&#39;IA en référençant les guidelines de boutons pour générer directement des boutons”">​</a></h2><p>Si vous voulez d&#39;abord faire des boutons, vous pouvez aussi coller directement le texte officiel des guidelines de boutons.</p><p>Par exemple, la définition du bouton par Atlassian est très courte :</p><blockquote><p><a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">« A button triggers an event or action. »</a></p></blockquote><p>Vous pouvez demander ceci à l&#39;IA :</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Référencez cette phrase d&#39;Atlassian :</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;A button triggers an event or action.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Aidez-moi à concevoir un ensemble de styles de boutons pour un back-office.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Je veux un bouton principal, un bouton secondaire, un bouton de suppression, et dites-moi respectivement où les utiliser.</span></span></code></pre></div><p>Ce type de prompt est particulièrement adapté aux débutants — c&#39;est essentiellement « coller le texte officiel + exprimer ses besoins ».</p><h2 id="_8-resume" tabindex="-1">8. Résumé <a class="header-anchor" href="#_8-resume" aria-label="Permalink to “8. Résumé”">​</a></h2><p>Référencer les guidelines de design pour concevoir des pages et des boutons, ce n&#39;est pas « ressembler à quelqu&#39;un », mais apprendre les choses suivantes :</p><ol><li>Organiser les pages avec une hiérarchie, plutôt qu&#39;empiler du contenu</li><li>Exprimer la priorité des actions avec des niveaux de boutons, plutôt que de rendre tous les boutons également voyants</li><li>Guider le design avec les définitions, les frontières et les critères de jugement des guidelines de design</li><li>Quand l&#39;IA référence les guidelines des autres, elle référence les « principes et structures », et non seulement l&#39;habillage</li></ol><p>Quand vous utilisez les guidelines de cette manière, vous ne référenciez pas seulement un style, mais une méthode de pensée de design mature.</p><hr><h2 id="references" tabindex="-1">Références <a class="header-anchor" href="#references" aria-label="Permalink to “Références”">​</a></h2><p>Les liens suivants proviennent tous de systèmes de design officiels ou de la documentation officielle :</p><ul><li>Apple Human Interface Guidelines : <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">Overview</a></li><li>Apple Human Interface Guidelines : <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">Menus</a></li><li>Apple Human Interface Guidelines : <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">Alerts</a></li><li>Apple Human Interface Guidelines : <a href="https://developer.apple.com/design/human-interface-guidelines/buttons" target="_blank" rel="noreferrer">Buttons</a></li><li>Apple Archive : <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/HowMenusWork.html" target="_blank" rel="noreferrer">How Menus Work</a></li><li>Apple Archive : <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">Managing Pop-Up Buttons and Pull-Down Lists</a></li><li>Material Design : <a href="https://m3.material.io/components/buttons/overview" target="_blank" rel="noreferrer">Buttons overview</a></li><li>Material Design : <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">Menus</a></li><li>Microsoft Fluent 2 : <a href="https://fluent2.microsoft.design/get-started/design" target="_blank" rel="noreferrer">Start designing</a></li><li>Microsoft Fluent 2 : <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">Menu usage</a></li><li>Microsoft Fluent 2 : <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">Button usage</a></li><li>Atlassian Design System : <a href="https://atlassian.design/foundations/" target="_blank" rel="noreferrer">Foundations</a></li><li>Atlassian Design System : <a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">Button</a></li></ul>`,146)])])}const g=t(a,[["render",l]]);export{m as __pageData,g as default};
